import{z as l,x as o,o as B,c as A,q as C,j as n,D as e,d as r,s,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"CBDC","description":"","frontmatter":{"title":"CBDC","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/cbdc.md","filePath":"econ/cbdc.md","lastUpdated":1791413859000}'),d={name:"econ/cbdc.md"};function D(p,a,c,m,h,u){const t=o("Mermaid");return B(),A("div",null,[a[2]||(a[2]=C('<h1 id="cbdc" tabindex="-1">CBDC <a class="header-anchor" href="#cbdc" aria-label="Permalink to &quot;CBDC&quot;">​</a></h1><div class="epigraph"><p>央行数字货币是公共部门的新负债科目：可以像现金，也可以像付息储备的零售版。设计决定它挤的是存款、现金还是 MMF。</p><footer>—— 对照 BIS 对 CBDC 的综述；Brunnermeier and Niepelt 对公共货币与私人货币共存的讨论</footer></div><p><a href="/econ/repo-mmf">上一课</a>把私人短债生态钉住。缺口是：若央行直接给公众一个数字账户，中介和地板工具怎么改。本课钉 CBDC 的宏观逻辑，美元主导下一课才出国界。不写某试点的 UI。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CBDC 可以是现金的替代（匿名、不计息）或存款的替代（账户、或付息）。后者在危机时提供「公共安全账户」，可能加速银行挤兑（DD 加上一个永远不挤的选项）。若计息，它还与准备金、ON RRP 抢利率走廊。缺口是用已有的中介与主导语言选设计，而不是「要不要数字化」的口号。</p><p><span class="marginnote">CBDC 可以翻译成「央行直接开给老百姓的账户或数字现金」：纸币本来就是央行负债，只是你得用现金箱装着；CBDC 把它变成手机里的央行余额。它与支付宝、微信零钱的本质区别在科目——那背后是商业银行负债，银行可能倒闭；CBDC 是央行负债，没有这一层信用风险。</span></p><p><span class="marginnote">Andolfatto；Keister and Sanches 讨论 CBDC 与银行信贷。Piazzesi and Schneider 对支付与中介。中国 e-CNY 是零售支付试点，不等于计息 CBDC 宏观。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三个旋钮：准入（批发 vs 零售）、报酬（零利率 vs 政策利率附近）、持有上限。宏观映射：零售不计息 ≈ 现金；零售计息 ≈ 把 HANK 里的安全资产供给外生扩大；批发 CBDC ≈ 给非银一个储备账户。与财政主导：付息 CBDC 是更多名义公共债。与影子：若 CBDC 替代 MMF，ON RRP 需求下降。</p>',9)),(B(),n(i,null,{default:e(()=>[s(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CASH%5B%22%E7%8E%B0%E9%87%91%E5%9E%8B%22%5D%20--%3E%20PAY%5B%22%E6%94%AF%E4%BB%98%22%5D%0A%20%20DEP%5B%22%E5%AD%98%E6%AC%BE%E5%9E%8B%22%5D%20--%3E%20RUN%5B%22%E6%8C%A4%E5%85%91%E9%80%89%E9%A1%B9%22%5D%0A%20%20INT%5B%22%E8%AE%A1%E6%81%AF%22%5D%20--%3E%20FLOOR%5B%22%E8%B5%B0%E5%BB%8A%E4%B8%8E%E4%B8%AD%E4%BB%8B%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"银行负债若被 CBDC 置换，除非央行把资金贷回银行，信贷供给要走新的 \\(\\phi\\)。批发 CBDC 改变谁能持有央行负债，等于重划「银行」边界——这里的边界是字面义：谁能直接开央行账户，谁就站在中介边界内。匿名性与 AML 是微观约束，会限制现金型能做多大。",-1)),a[5]||(a[5]=E("p",null,"计息是把挤兑加速器接上电门。零息 CBDC 平时惰性如现金，危机里仍是一键搬家的安全选项：DD 的序贯服务与营业时间被点击替代，存款搬家只受指尖限制，利率弹性不必高，速度就够致命。若 CBDC 付息，搬家在平时就有价格：银行得抬存款利率留客，利差变薄，信贷供给要么收缩、要么迁向更险的资产。这同时是一场「争夺走廊」：计息 CBDC 与准备金利息、ON RRP 在同一条走廊里抢锚，公众成了央行一个规模内生、无法闸门的对手方，走廊的量价关系要重写。Keister and Sanches 的权衡正落在这里：支付效率换存款流失与信贷收缩，三个旋钮的每个组合都在这三者之间分配。",-1)),(B(),n(i,null,{default:e(()=>[s(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%8D%B1%E6%9C%BA%E4%BF%A1%E5%8F%B7%E5%87%BA%E7%8E%B0%22%5D%20--%3E%20W%5B%22%E5%85%AC%E4%BC%97%E4%B8%80%E9%94%AE%E6%90%AC%E5%90%91%20CBDC%22%5D%0A%20%20W%20--%3E%20V%5B%22%E5%AD%98%E6%AC%BE%E6%B5%81%E5%A4%B1%E4%B8%8D%E5%86%8D%E5%8F%97%E6%8E%92%E9%98%9F%E9%99%90%E5%88%B6%22%5D%0A%20%20V%20--%3E%20B%5B%22%E9%93%B6%E8%A1%8C%E4%B8%BA%E7%95%99%E5%AE%A2%E6%8A%AC%E9%AB%98%E5%AD%98%E6%AC%BE%E5%88%A9%E7%8E%87%22%5D%0A%20%20B%20--%3E%20M%5B%22%E5%88%A9%E5%B7%AE%E5%8F%98%E8%96%84%EF%BC%8C%E5%88%A9%E6%B6%A6%E5%8F%97%E5%8E%8B%22%5D%0A%20%20M%20--%3E%20L%5B%22%E4%BF%A1%E8%B4%B7%E6%94%B6%E7%BC%A9%EF%BC%8C%E6%88%96%E8%BF%81%E5%90%91%E9%AB%98%E9%A3%8E%E9%99%A9%E8%B5%84%E4%BA%A7%22%5D%0A%20%20L%20--%3E%20K%5B%22%E8%AE%A1%E6%81%AF%20CBDC%20%E4%B8%8E%E5%87%86%E5%A4%87%E9%87%91%E3%80%81ON%20RRP%20%E4%BA%89%E5%A4%BA%E8%B5%B0%E5%BB%8A%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=C('<p><span class="marginnote">直觉类比：传统挤兑像在营业厅排队取钱，银行还能用「等明天开门」拖慢速度；CBDC 把排队换成点手机，营业时间约束被指尖替代。关键不在搬家的钱有多少，而在快——DD 模型里只要所有人都相信别人会点，恐慌就自我实现，速度本身就是均衡的武器。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不预测发行时间表，不把 CBDC 写成已替代美元。下一课国际：美元负债网络比零售 CBDC 更硬。不讨论钱包密码学。</p><p><span class="marginnote">常见误区：以为 CBDC 只是「换个方式付款」，宏观上无关紧要。它的科目归属决定一切：记在央行账上是公共负债扩张，替代存款则抽走银行的资金来源，计息则直接参与利率走廊。同样的技术，三个设计旋钮拨在不同位置，就是三种完全不同的宏观动物。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CBDC 的宏观效应取决于它替代现金、存款还是货基。</li><li>计息零售 CBDC 是新的挤兑与走廊工具。</li><li>计息引出存款搬家的利率弹性与「争夺走廊」：公众对手方让量价关系内生。</li><li>出处：BIS CBDC 综述；Brunnermeier–Niepelt；Keister–Sanches。</li></ul>',6))])}const b=l(d,[["render",D]]);export{_ as __pageData,b as default};
